INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > Microservices
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Microservices immer unabhängig voneinander bereitgestellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Unabhängige Bereitstellung ist ein Kernprinzip"}, {"text": "Nein", "correct": false, "because": "Abhängigkeit widerspricht dem Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Microservice mehrere Funktionen in einem Dienst kombinieren?', 2, '[{"text": "Nein", "correct": true, "because": "Microservices sollten eine einzige Funktion erfüllen"}, {"text": "Ja", "correct": false, "because": "Multifunktionalität widerspricht Single Responsibility"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Nutzung von Microservices immer komplexer als eine monolithische Architektur?', 2, '[{"text": "Ja", "correct": true, "because": "Verteilte Systeme erhöhen die Komplexität"}, {"text": "Nein", "correct": false, "because": "Komplexität ist typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Microservices ohne Netzwerkkommunikation funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Sie kommunizieren über Netzwerke"}, {"text": "Ja", "correct": false, "because": "Netzwerk ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Microservices immer in Containern wie Docker laufen?', 2, '[{"text": "Nein", "correct": true, "because": "Container sind üblich, aber nicht zwingend"}, {"text": "Yes", "correct": false, "because": "Andere Deployments möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal definiert Microservices am besten?', 2, '[{"text": "Unabhängige Dienste", "correct": true, "because": "Jeder Dienst ist eigenständig"}, {"text": "Einheitliche Codebasis", "correct": false, "because": "Typisch für Monolithen"}, {"text": "Zentrale Verwaltung", "correct": false, "because": "Dezentral ist Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil von Microservices ist am bedeutendsten?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Einzelne Dienste können separat skaliert werden"}, {"text": "Einfache Entwicklung", "correct": false, "because": "Komplexität höher"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil tritt bei Microservices am häufigsten auf?', 2, '[{"text": "Netzwerklatenz", "correct": true, "because": "Kommunikation über Netzwerk verursacht Verzögerungen"}, {"text": "Mangelnde Sicherheit", "correct": false, "because": "Nicht spezifisch"}, {"text": "Langsame Bereitstellung", "correct": false, "because": "Eher schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wird für die Kommunikation zwischen Microservices am häufigsten verwendet?', 2, '[{"text": "RESTful APIs", "correct": true, "because": "Leichtgewichtig und weit verbreitet"}, {"text": "Direkte Datenbankzugriffe", "correct": false, "because": "Widerspricht Unabhängigkeit"}, {"text": "Shared Memory", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sollte bei der Planung von Microservices Priorität haben?', 2, '[{"text": "Single Responsibility", "correct": true, "because": "Jeder Dienst eine Funktion"}, {"text": "Maximale Kopplung", "correct": false, "because": "Lose Kopplung ist Ziel"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Dezentral ist besser"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften definieren Microservices?', 4, '[{"text": "Unabhängige Bereitstellung", "correct": true, "because": "Kernprinzip"}, {"text": "Dezentrale Datenverwaltung", "correct": true, "because": "Jeder Dienst eigene Daten"}, {"text": "Lose Kopplung", "correct": true, "because": "Wenig Abhängigkeit"}, {"text": "Monolithische Struktur", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Microservices?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Technologiewahl pro Dienst"}, {"text": "Skalierbarkeit", "correct": true, "because": "Individuelle Skalierung"}, {"text": "Wartbarkeit", "correct": true, "because": "Kleine Einheiten einfacher"}, {"text": "Geringere Komplexität", "correct": false, "because": "Komplexität steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen treten bei Microservices auf?', 4, '[{"text": "Verteilte Systemkomplexität", "correct": true, "because": "Mehr Dienste, mehr Verwaltung"}, {"text": "Netzwerklatenz", "correct": true, "because": "Kommunikation verzögert"}, {"text": "Datenkonsistenz", "correct": true, "because": "Dezentrale Daten schwierig"}, {"text": "Einfache Bereitstellung", "correct": false, "because": "Komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen den Einsatz von Microservices?', 3, '[{"text": "Docker", "correct": true, "because": "Containerisierung"}, {"text": "Kubernetes", "correct": true, "because": "Orchestrierung"}, {"text": "REST-APIs", "correct": true, "because": "Kommunikation"}, {"text": "Monolith-Frameworks", "correct": false, "because": "Nicht passend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten bei der Entwicklung von Microservices beachtet werden?', 3, '[{"text": "Single Responsibility", "correct": true, "because": "Eine Funktion pro Dienst"}, {"text": "Dezentralität", "correct": true, "because": "Unabhängige Steuerung"}, {"text": "Robustheit", "correct": true, "because": "Fehlertoleranz"}, {"text": "Enge Kopplung", "correct": false, "because": "Lose Kopplung ist Ziel"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Microservices sind unabhängig bereitstellbar. b) Sie sind immer einfacher zu entwickeln als Monolithen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bereitstellbar ja, Entwicklung komplexer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Microservices erhöhen die Skalierbarkeit. b) Sie funktionieren ohne Netzwerkkommunikation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skalierbarkeit ja, Netzwerk nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Microservices sollten lose gekoppelt sein. b) Sie erfordern immer Container wie Docker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lose Kopplung ja, Container optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Netzwerklatenz ist ein Nachteil von Microservices. b) Sie sind für kleine Projekte ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz ja, kleine Projekte eher Monolith"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Microservices fördern Flexibilität in der Technologiewahl. b) Sie haben eine einheitliche Codebasis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, einheitliche Basis nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

